            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Chroń, Panie, wątłą mojej duszy zieleń, Od podeptania i martwych spopieleń, Abym wśród życia Ostatniej Wieczerzy Czuł jej aromat balsamiczny, świeży.", Author = "Leopold Staff" },
