            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Głupiec głupotę kosi, mędrzec – mądrość. Każdy znajduje to, czego mu trzeba.", Author = "Leopold Staff" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Gorce chmurne i dżdżyste, zielone manowce, Smreki, szałasy kryte szczerniałymi deski, Piargi, liche kartofle i chude owieski, Musujące potoki i skubiące owce.", Author = "Leopold Staff" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "I cóż za prawdą świadczy bardziej niż to, że błąd ma więcej czaru?", Author = "Leopold Staff" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Im bardziej uszlachetniasz swe serce, tym oblicze twej sztuki bardziej prawe.", Author = "Leopold Staff" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "I przeklniesz dzień, gdym słuchał twego rozkazania, Choć nie zgadniesz, że jutro opuszczę twe progi: Bom, błądząc, nad cię błędne swe pokochał drogi...", Author = "Leopold Staff" },
