            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Jedyna godna rzecz na świecie: twórczość, A szczyt twórczości to tworzenie siebie.", Author = "Leopold Staff" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Już? Tak prędko? Co to było? Coś strwonione? Pierzchło skrycie? Czy nie młodość swą przeżyło? Ach, więc to już było… życie?", Author = "Leopold Staff" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Kochać i tracić, pragnąć i żałować, Padać boleśnie i znów się podnosić, Krzyczeć tęsknocie „precz” i błagać „prowadź” Oto jest życie: nic, a jakże dosyć…", Author = "Leopold Staff" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Kto szuka Cię, już znalazł Ciebie; Już Cię ma, komu Ciebie trzeba; Kto tęskni w niebo Twe, jest w niebie; Kto głodny go, je z Twego chleba.", Author = "Leopold Staff" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Kwiaty na to są, ażeby więdły, ale serca są, aby kochały.", Author = "Leopold Staff" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Leżę na łodzi W wieczornej ciszy. Gwiazdy nade mną, Gwiazdy pode mną I gwiazdy we mnie.", Author = "Leopold Staff" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Lecz biskaś ty mi, bliska Jak żałość niezgłębiona... Serce się ściska I kona.", Author = "Leopold Staff" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Ma dola jest nieszczęsna, ma dola jest szczęśliwa! Muszę mieć zawsze w duszy to, na czym innym zbywa.", Author = "Leopold Staff" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Najgłębszy smutek szczęścia, że wszystko przemija.", Author = "Leopold Staff" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Nic mi, świecie, piękności twej zmącić niezdolne!", Author = "Leopold Staff" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Nic nie wiem. Nie mogę znaleźć butów, Nie mogę znaleźć siebie. Boli mnie głowa.", Author = "Leopold Staff" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Nie widzą Ciebie moje oczy, Nie słyszą Ciebie moje uszy; A jesteś światłem w mej pomroczy. A jesteś śpiewem w mojej duszy.", Author = "Leopold Staff" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Noc czarna, srebrna noc Świat nieskończony W czasie i przestrzeni. Pośrodku Droga Mleczna Któż po niej przechodzi? To przechodzi ludzkie pojęcie.", Author = "Leopold Staff" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "O, te wszystkie drobne, małe rzeczy, Z których każda rani i kaleczy, Tak bezpłodna, a jątrzy i skrzeczy.", Author = "Leopold Staff" },
