            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Obudził się wietrzyk Łagodny i miękki I brzozom podnosi Zielone sukienki.", Author = "Leopold Staff" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Od dawna zwiastowano, że bardziej niźli chleba Poezji trzeba w czasach, gdy wcale jej nie trzeba.", Author = "Leopold Staff" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Po minionych złych deszczach i burzy Powracają burze i złe deszcze Ale ciągle nadzieja mi wróży, Że to, czego czekam, przyjdzie jeszcze.", Author = "Leopold Staff" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Pokazałeś w wesołej herezji Przez swe fraszki fiołkowe i gęsie, Ile jest nonsensu w poezji Ile poezji w nonsensie.", Author = "Leopold Staff" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Słońce świeci, deszczyk pada, Czarownica się podkrada. Słońce świeci, deszczyk pada, Czarownica dziwy składa.", Author = "Leopold Staff" },
