            new Quote { Id = "https://pl.wikiquote.org/wiki/Leopold_Staff", Text = "Zbiegać za jednym klejnotem pustynie, Iść w toń za perłą o cudu urodzie, Ażeby po nas zostały jedynie Ślady na piasku i kręgi na wodzie.", Author = "Leopold Staff" },
